templates.Tabs:
"use client"

import type { ComponentProps as PlaygroundComponentProps } from "react"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

const playgroundProps: Partial<PlaygroundComponentProps<typeof Tabs>> = /*__DS_PROPS__*/ {}


export function TabsDemo() {
  return (
    <Tabs defaultValue="account" className="w-full max-w-md">{playgroundProps.children ?? <>
      <TabsList>
        <TabsTrigger value="account">Account</TabsTrigger>
        <TabsTrigger value="password">Password</TabsTrigger>
      </TabsList>
      <TabsContent value="account" className="text-sm text-muted-foreground">
        Make changes to your account here.
      </TabsContent>
      <TabsContent value="password" className="text-sm text-muted-foreground">
        Change your password here.
      </TabsContent>
    </>}</Tabs>
  )
}

